def minEatingSpeed(piles, h):
    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi) // 2
        hours = sum((p + mid - 1) // mid for p in piles)
        if hours <= h:
            hi = mid
        else:
            lo = mid + 1
    return lo

def merge(intervals):
    intervals = sorted(intervals)
    res = []
    for s, e in intervals:
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

def coinChange(coins, amount):
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

def numIslands(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not seen[r][c]:
                count += 1
                seen[r][c] = True
                stack = [(r, c)]
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
    return count

def topKFrequent(nums, k):
    count = {}
    for x in nums:
        count[x] = count.get(x, 0) + 1
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, c in count.items():
        buckets[c].append(x)
    res = []
    for c in range(len(nums), 0, -1):
        for x in buckets[c]:
            res.append(x)
            if len(res) == k:
                return res
    return res

def twoSumSorted(numbers, target):
    lo, hi = 0, len(numbers) - 1
    while lo < hi:
        total = numbers[lo] + numbers[hi]
        if total == target:
            return [lo + 1, hi + 1]
        if total < target:
            lo += 1
        else:
            hi -= 1
    return []

def findMin(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

def characterReplacement(s, k):
    count = {}
    left = 0
    best = 0
    for right, c in enumerate(s):
        count[c] = count.get(c, 0) + 1
        while (right - left + 1) - max(count.values()) > k:
            count[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def minSubArrayLen(target, nums):
    best = 0
    left = 0
    total = 0
    for right, x in enumerate(nums):
        total += x
        while total >= target:
            length = right - left + 1
            if best == 0 or length < best:
                best = length
            total -= nums[left]
            left += 1
    return best

def subarraySum(nums, k):
    seen = {0: 1}
    prefix = 0
    count = 0
    for x in nums:
        prefix += x
        count += seen.get(prefix - k, 0)
        seen[prefix] = seen.get(prefix, 0) + 1
    return count

def rob(nums):
    skip, take = 0, 0      # best loot ignoring / including the previous house's decision
    for x in nums:
        skip, take = max(skip, take), skip + x
    return max(skip, take)

def canJump(nums):
    far = 0
    for i, x in enumerate(nums):
        if i > far:
            return False
        far = max(far, i + x)
    return far >= len(nums) - 1

from bisect import bisect_left


def lengthOfLIS(nums):
    tails = []
    for x in nums:
        k = bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x
    return len(tails)

def numDecodings(s):
    MOD = 1_000_000_007
    prev2, prev1 = 0, 1          # ways(i-2), ways(i-1); ways(0) = 1
    for i in range(1, len(s) + 1):
        cur = 0
        if s[i - 1] != '0':
            cur += prev1
        if i >= 2 and '10' <= s[i - 2:i] <= '26':
            cur += prev2
        prev2, prev1 = prev1, cur % MOD
    return prev1

def longestCommonSubsequence(text1, text2):
    m, n = len(text1), len(text2)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        a = text1[i - 1]
        for j in range(1, n + 1):
            if a == text2[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return prev[n]

def insertInterval(intervals, newInterval):
    start, end = newInterval
    res = []
    i, n = 0, len(intervals)
    while i < n and intervals[i][1] < start:
        res.append(list(intervals[i]))
        i += 1
    while i < n and intervals[i][0] <= end:
        start = min(start, intervals[i][0])
        end = max(end, intervals[i][1])
        i += 1
    res.append([start, end])
    while i < n:
        res.append(list(intervals[i]))
        i += 1
    return res

def minMeetingRooms(intervals):
    starts = sorted(iv[0] for iv in intervals)
    ends = sorted(iv[1] for iv in intervals)
    rooms = 0
    e = 0
    for s in starts:
        if ends[e] <= s:
            e += 1          # a meeting finished, reuse its room
        else:
            rooms += 1
    return rooms

def rotate(matrix):
    n = len(matrix)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            res[j][n - 1 - i] = matrix[i][j]
    return res

def maxAreaOfIsland(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not seen[r][c]:
                seen[r][c] = True
                stack = [(r, c)]
                area = 0
                while stack:
                    y, x = stack.pop()
                    area += 1
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                best = max(best, area)
    return best

from collections import deque


def orangesRotting(grid):
    rows, cols = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    q = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 2:
                q.append((r, c))
            elif g[r][c] == 1:
                fresh += 1
    minutes = 0
    while q and fresh:
        for _ in range(len(q)):
            y, x = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and g[ny][nx] == 1:
                    g[ny][nx] = 2
                    fresh -= 1
                    q.append((ny, nx))
        minutes += 1
    return -1 if fresh else minutes

import heapq


def networkDelayTime(times, n, k):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[k] = 0
    heap = [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    worst = max(dist[1:])
    return -1 if worst == INF else worst

def countAnagramWindows(s, p):
    n, m = len(s), len(p)
    if m > n:
        return 0
    bal = {}
    for c in p:
        bal[c] = bal.get(c, 0) + 1
    nonzero = len(bal)
    count = 0

    def shift(c, d):
        nonlocal nonzero
        before = bal.get(c, 0)
        after = before + d
        bal[c] = after
        if before == 0 and after != 0:
            nonzero += 1
        elif before != 0 and after == 0:
            nonzero -= 1

    for i in range(n):
        shift(s[i], -1)
        if i >= m:
            shift(s[i - m], 1)
        if i >= m - 1 and nonzero == 0:
            count += 1
    return count

def minDeletionsToOrder(s):
    b = 0
    best = 0
    for c in s:
        if c == 'b':
            b += 1
        else:
            best = min(best + 1, b)
