def searchRange(nums, target):
    def lower(strict):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < target or (strict and nums[mid] == target):
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower(False)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, lower(True) - 1]

def shipWithinDays(weights, days):
    def need(cap):
        d, load = 1, 0
        for w in weights:
            if load + w > cap:
                d += 1
                load = 0
            load += w
        return d

    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        if need(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo

def longestOnes(nums, k):
    left = zeros = best = 0
    for right, x in enumerate(nums):
        if x == 0:
            zeros += 1
        while zeros > k:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def eraseOverlapIntervals(intervals):
    kept = 0
    last_end = None
    for s, e in sorted(intervals, key=lambda x: x[1]):
        if last_end is None or s >= last_end:
            kept += 1
            last_end = e
    return len(intervals) - kept

def findMinArrowShots(points):
    arrows = 0
    pos = None
    for s, e in sorted(points, key=lambda x: x[1]):
        if pos is None or s > pos:
            arrows += 1
            pos = e
    return arrows

def canCompleteCircuit(gas, cost):
    if sum(gas) < sum(cost):
        return -1
    start = 0
    tank = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:
            start = i + 1
            tank = 0
    return start

def minJumps(nums):
    jumps = 0
    cur_end = 0
    far = 0
    for i in range(len(nums) - 1):
        far = max(far, i + nums[i])
        if i == cur_end:
            jumps += 1
            cur_end = far
    return jumps

def spiralOrder(matrix):
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    out = []
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            out.append(matrix[top][j])
        top += 1
        for i in range(top, bottom + 1):
            out.append(matrix[i][right])
        right -= 1
        if top <= bottom:
            for j in range(right, left - 1, -1):
                out.append(matrix[bottom][j])
            bottom -= 1
        if left <= right:
            for i in range(bottom, top - 1, -1):
                out.append(matrix[i][left])
            left += 1
    return out

def setZeroes(matrix):
    m, n = len(matrix), len(matrix[0])
    first_row = any(matrix[0][j] == 0 for j in range(n))
    first_col = any(matrix[i][0] == 0 for i in range(m))
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if first_row:
        for j in range(n):
            matrix[0][j] = 0
    if first_col:
        for i in range(m):
            matrix[i][0] = 0
    return matrix

import heapq

def kClosest(points, k):
    heap = []
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

def canPartition(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    reach = [False] * (target + 1)
    reach[0] = True
    for x in nums:
        for s in range(target, x - 1, -1):
            if reach[s - x]:
                reach[s] = True
    return reach[target]

def findCircleNum(isConnected):
    n = len(isConnected)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    comps = n
    for i in range(n):
        row = isConnected[i]
        for j in range(i + 1, n):
            if row[j]:
                a, b = find(i), find(j)
                if a != b:
                    parent[a] = b
                    comps -= 1
    return comps

def findRedundantConnection(edges):
    parent = list(range(len(edges) + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]
        parent[ra] = rb
    return []

def combinationSum2(candidates, target):
    cs = sorted(candidates)
    res = []
    cur = []

    def go(start, remain):
        if remain == 0:
            res.append(cur[:])
            return
        for i in range(start, len(cs)):
            if cs[i] > remain:
                break
            if i > start and cs[i] == cs[i - 1]:
                continue
            cur.append(cs[i])
            go(i + 1, remain - cs[i])
            cur.pop()

    go(0, target)
    return res

from collections import deque


def shortestPathBinaryMatrix(grid):
    n = len(grid)
    if grid[0][0] or grid[n - 1][n - 1]:
        return -1
    dist = [[0] * n for _ in range(n)]
    dist[0][0] = 1
    q = deque([(0, 0)])
    while q:
        r, c = q.popleft()
        if r == n - 1 and c == n - 1:
            return dist[r][c]
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not grid[nr][nc] and not dist[nr][nc]:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
    return -1

def maxProfit(prices):
    hold = -10 ** 9
    sold = 0
    free = 0
    for p in prices:
        new_hold = max(hold, free - p)
        new_sold = hold + p
        new_free = max(free, sold)
        hold, sold, free = new_hold, new_sold, new_free
    return max(sold, free)

def trap(height):
    lo, hi = 0, len(height) - 1
    left = right = water = 0
    while lo < hi:
        if height[lo] < height[hi]:
            left = max(left, height[lo])
            water += left - height[lo]
            lo += 1
        else:
            right = max(right, height[hi])
            water += right - height[hi]
            hi -= 1
    return water

from collections import deque

def maxSlidingWindow(nums, k):
    dq = deque()
    out = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

def minWindow(s, t):
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    missing = len(t)
    best_start, best_len = 0, len(s) + 1
    left = 0
    for right, c in enumerate(s):
        if need.get(c, 0) > 0:
            missing -= 1
        need[c] = need.get(c, 0) - 1
        while missing == 0:
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return "" if best_len > len(s) else s[best_start:best_start + best_len]

def minDistance(word1, word2):
    n, m = len(word1), len(word2)
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            if word1[i - 1] == word2[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
        prev = cur
    return prev[m]

def totalNQueens(n):
    cols, d1, d2 = set(), set(), set()

    def place(r):
        if r == n:
            return 1
        total = 0
        for c in range(n):
            if c in cols or (r - c) in d1 or (r + c) in d2:
                continue
            cols.add(c)
            d1.add(r - c)
            d2.add(r + c)
            total += place(r + 1)
            cols.remove(c)
            d1.remove(r - c)
            d2.remove(r + c)
        return total

    return place(0)

def findLowerMedian(a, b):
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    L = (m + n - 1) // 2 + 1          # how many of the smallest elements form the left part
    lo, hi = max(0, L - n), min(m, L)  # i = how many of them come from a
    while lo < hi:
        i = (lo + hi) // 2
        j = L - i
        if a[i] < b[j - 1]:
            lo = i + 1
        else:
            hi = i
    i = lo
    j = L - i
    best = None
    if i > 0:
        best = a[i - 1]
    if j > 0 and (best is None or b[j - 1] > best):
        best = b[j - 1]
    return best

def firstMissingPositive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

def longestValidParentheses(s):
    stack = [-1]
    best = 0
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

def maxCoins(nums):
    a = [1] + list(nums) + [1]
    m = len(a)
    dp = [[0] * m for _ in range(m)]
    for gap in range(2, m):
        for l in range(m - gap):
            r = l + gap
            lr = a[l] * a[r]
            best = 0
            for k in range(l + 1, r):
                v = dp[l][k] + dp[k][r] + lr * a[k]
                if v > best:
                    best = v
            dp[l][r] = best
    return dp[0][m - 1]

def isMatch(s, p):
    m, n = len(s), len(p)
    nxt = [False] * (n + 1)          # row i + 1; start with i = m (empty rest of text)
    nxt[n] = True
    for j in range(n - 2, -1, -1):
        nxt[j] = p[j + 1] == '*' and nxt[j + 2]
    # nxt now describes i = m
    for i in range(m - 1, -1, -1):
        cur = [False] * (n + 1)
        for j in range(n - 1, -1, -1):
            first = p[j] == s[i] or p[j] == '.'
            if j + 1 < n and p[j + 1] == '*':
                cur[j] = cur[j + 2] or (first and nxt[j])
            else:
                cur[j] = first and nxt[j + 1]
        nxt = cur
    return nxt[0]

def canPartitionKSubsets(nums, k):
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    a = sorted(nums)
    if a[-1] > target:
        return False
    n = len(a)
    full = (1 << n) - 1
    dead = set()

    def go(mask, cur):
        if mask == full:
            return True
        if mask in dead:
            return False
        for i in range(n):
            if mask >> i & 1:
                continue
            if cur + a[i] > target:
                break
            if i and a[i] == a[i - 1] and not (mask >> (i - 1) & 1):
                continue
            nxt = cur + a[i]
            if go(mask | (1 << i), 0 if nxt == target else nxt):
                return True
        dead.add(mask)
        return False

    return go(0, 0)

def longestIncreasingPath(matrix):
    rows, cols = len(matrix), len(matrix[0])
    order = sorted((matrix[r][c], r, c) for r in range(rows) for c in range(cols))
    length = [[1] * cols for _ in range(rows)]
    best = 1
    for v, r, c in order:
        m = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] < v and length[nr][nc] > m:
                m = length[nr][nc]
        length[r][c] = m + 1
        if length[r][c] > best:
            best = length[r][c]
    return best

def numDistinct(s, t):
    m = len(t)
    dp = [0] * (m + 1)
    dp[0] = 1
    for c in s:
        for j in range(m, 0, -1):
            if t[j - 1] == c:
                dp[j] += dp[j - 1]
    return dp[m]

def shortestPalindromeLength(s):
    n = len(s)
    t = s + '#' + s[::-1]
    pi = [0] * len(t)
    for i in range(1, len(t)):
        k = pi[i - 1]
        while k and t[i] != t[k]:
            k = pi[k - 1]
        if t[i] == t[k]:
            k += 1
        pi[i] = k
    return 2 * n - pi[-1]

def splitArray(nums, k):
    def pieces(limit):
        count, cur = 1, 0
        for x in nums:
            if cur + x > limit:
                count += 1
                cur = 0
            cur += x
        return count

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def shortestSubarray(nums, k):
    from collections import deque
    n = len(nums)
    pre = [0] * (n + 1)
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    best = n + 1
    dq = deque()
    for j in range(n + 1):
        while dq and pre[j] - pre[dq[0]] >= k:
            best = min(best, j - dq.popleft())
        while dq and pre[dq[-1]] >= pre[j]:
            dq.pop()
        dq.append(j)
    return best if best <= n else -1

def candy(ratings):
    n = len(ratings)
    give = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            give[i] = give[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1] and give[i] <= give[i + 1]:
            give[i] = give[i + 1] + 1
    return sum(give)

def numIslands2(m, n, positions):
    parent = list(range(m * n))
    size = [1] * (m * n)
    land = [False] * (m * n)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    count = 0
    out = []
    for r, c in positions:
        idx = r * n + c
        if not land[idx]:
            land[idx] = True
            count += 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and land[nr * n + nc]:
                    a, b = find(idx), find(nr * n + nc)
                    if a != b:
                        if size[a] < size[b]:
                            a, b = b, a
                        parent[b] = a
                        size[a] += size[b]
                        count -= 1
        out.append(count)
    return out

def minCut(s):
    n = len(s)
    cuts = [i - 1 for i in range(n + 1)]
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):
            while l >= 0 and r < n and s[l] == s[r]:
                if cuts[l] + 1 < cuts[r + 1]:
                    cuts[r + 1] = cuts[l] + 1
                l -= 1
                r += 1
    return cuts[n]
